      footer: { desc: "Perusahaan penyedia layanan penagihan profesional (desk collection & field collection) yang berfokus pada kualitas, etika, dan pencapaian target terbaik.", usefulLinks: "Tautan Berguna", contactUs: "Hubungi Kami", address: "Ruko Rose Garden 5 No. 20, Grand Galaxy City, RT.002/RW.017, Jaka Setia, Kecamatan Bekasi Selatan, Kota Bekasi, Jawa Barat 17148", privacy: "Kebijakan Privasi", terms: "Ketentuan Layanan", rights: "Hak Cipta Dilindungi." },
      about: { hero: { title: "Identitas Perusahaan", desc: "Mengenal PT Perdana Usaha Madani melalui latar belakang pendirian, visi dan misi, nilai perusahaan, serta jajaran pimpinan dan tim operasional." }, history: { title: "Tentang Kami", p1: "PT Perdana Usaha Madani didirikan secara resmi di Bekasi pada tanggal 13 Oktober 2023 berdasarkan Akta No. 03. Perusahaan ini diprakarsai oleh Tumpak Benny Marpaung dan Rosinta Uli Manurung, serta didukung oleh tim profesional yang memiliki rekam jejak panjang dan pengalaman mendalam di bidang layanan pemulihan kredit bermasalah (Desk Collection).", p2: "Berpusat di Ruko Rose Garden 5 No. 20, Galaxy, Bekasi Selatan, kami berkomitmen membangun organisasi yang berorientasi pada kepuasan mitra bisnis dengan senantiasa menjunjung tinggi integritas, kejujuran, dan profesionalisme. PT Perdana Usaha Madani hadir sebagai mitra strategis yang memberikan solusi inovatif dan aplikatif bagi sektor perbankan maupun non-perbankan dalam menavigasi serta mengatasi berbagai tantangan kredit." }, legal: { title: "Legalitas Korporasi", l1: { title: "Akta Pendirian:", desc: "No. 03 (Tanggal 13 Oktober 2023)" }, l2: { title: "SK Kemenkumham:", desc: "Pengesahan Resmi Badan Hukum PT" }, l3: { title: "NIB (Nomor Induk Berusaha):", desc: "Terdaftar Resmi Terintegrasi OSS" }, l4: { title: "NPWP Badan Usaha:", desc: "Terdaftar Wajib Pajak Badan Usaha" } }, vision: { title: "Visi Kami", desc: "Menjadi perusahaan yang profesional dan terpercaya di bidang jasa penagihan utang. Kami berkomitmen untuk menjadi pihak yang diandalkan oleh lembaga perbankan maupun non-perbankan, serta berperan sebagai mitra bisnis yang harmonis untuk jangka panjang." }, mission: { title: "Misi Kami", desc: "Berperan aktif dalam pengembangan sektor perbankan dan non-perbankan di Indonesia, khususnya dalam memulihkan kredit bermasalah. Kami hadir sebagai benteng pertahanan terakhir yang memberikan solusi penyelesaian secara terukur." }, values: { title: "Nilai Perusahaan (Core Values)", v1: { title: "Etika & Kepatuhan", desc: "Kepatuhan ketat terhadap OJK dan BI. Praktik penagihan dilakukan dengan sopan, menghormati hak konsumen, dan menolak keras segala bentuk intimidasi." }, v2: { title: "Transparansi Data", desc: "Tata kelola yang transparan melalui laporan kinerja yang akurat dan catatan data yang valid, serta menjaga kerahasiaan data konsumen sesuai standar privasi data." }, v3: { title: "Maksimalisasi Aset", desc: "Disiplin dan strategi penagihan yang terukur untuk menekan angka NPL/DPD dan menjaga kesehatan arus kas mitra." } }, team: { title: "Jajaran Kepemimpinan Perusahaan", desc: "Didukung oleh jajaran profesional dengan pengalaman mumpuni dalam manajemen penagihan, keuangan, dan kontrol kualitas.", roles: { komisaris: "Komisaris Utama", commissioner: "Commissioner", direktur: "Direktur", manager: "Manager", finance: "Finance", hrd: "HRD / Admin", qc: "Quality Control" } } },
