      hero: { title1: "Profesionalisme dalam", title2: "Resolusi Kredit Anda.", desc: "Sebagai rakan kongsi yang dipercayai, kami mengutamakan etika, pematuhan (OJK/AFPI), dan kecekapan dalam pemulihan aset anda.", btnServices: "Lihat Perkhidmatan Kami", btnAbout: "Tentang Syarikat" },
