      strength: { title1: "Mengapa Memilih", title2: "PT Perdana Usaha Madani?", desc: "Kekuatan kami berpusat pada operasi yang tersistem dan kawalan kualiti yang ketat.", btn: "Profil Syarikat", system: { title: "Operasi Berasaskan Sistem", desc: "Operasi pusat panggilan & kutipan meja sepenuhnya berasaskan sistem." }, qc: { title: "Kawalan Kualiti Rutin", desc: "Memantau prestasi ejen secara rutin untuk memastikan pematuhan SOP." }, training: { title: "Latihan Rutin", desc: "Memberikan latihan rutin kepada semua kakitangan untuk meningkatkan kualiti rundingan." }, leader: { title: "Ketua Pasukan Kompeten", desc: "Diterajui oleh Ketua Pasukan yang berkebolehan." } },
